using NUnit.Framework;
using SaferAccessors.Tests;

namespace SaferAccessors.Analysis.Tests.Generators;

internal static class ConstructorAccessorGeneratorTests
{
	[Test]
	public static async Task GenerateAsync()
	{
		var code =
			"""
			using SaferAccessors;
			using System;

			[assembly: UnsafeAccessorMap(typeof(Test))]

			public class Test
			{
				private Test(string key, Guid id) { }
			}
			""";

		var generatedCode =
			"""
			// <auto-generated/>
			
			#nullable enable
			
			public static partial class TestExtensions
			{
				extension(global::Test)
				{
					[global::System.Runtime.CompilerServices.UnsafeAccessor(global::System.Runtime.CompilerServices.UnsafeAccessorKind.Constructor)]
					public extern static global::Test New(string key, global::System.Guid id);
				}
				
			}
			
			""";

		await TestAssistants.RunGeneratorAsync<SaferAccessorsGenerator>(code,
			[($"Test_Accessors.g.cs", generatedCode)],
			[]);
	}

	[Test]
	public static async Task GenerateWithGenericTypeAsync()
	{
		var code =
			"""
			using SaferAccessors;
			using System;

			[assembly: UnsafeAccessorMap(typeof(Test<>))]

			public class Test<T>
			{
				private Test(T key, Guid id) { }
			}
			""";

		var generatedCode =
			"""
			// <auto-generated/>
			
			#nullable enable
			
			public static partial class TestExtensions
			{
				extension<T>(global::Test<T>)
				{
					public static global::Test<T> New(T key, global::System.Guid id) =>
						TestAccessors<T>.New(key, id);
				}
				
				private static class TestAccessors<T>
				{
					[global::System.Runtime.CompilerServices.UnsafeAccessor(global::System.Runtime.CompilerServices.UnsafeAccessorKind.Constructor)]
					public extern static global::Test<T> New(T key, global::System.Guid id);
						
				}
			}
			
			""";

		await TestAssistants.RunGeneratorAsync<SaferAccessorsGenerator>(code,
			[($"Test_T_Accessors.g.cs", generatedCode)],
			[]);
	}
}